const THRESHOLDS = {"status":"DRAFT - placeholder pending Urbani (client input #14). Not agreed SLOs.","note":"Values are latency in milliseconds at the given percentile per request group, plus error-rate budgets. A developer laptop is not a 0.5 vCPU Fargate task: use --thresholdScale <factor> (Node runner) or -e THRESHOLD_SCALE=<factor> (k6) to stretch every latency limit. Error rates are never scaled.","groups":{"read":{"description":"Read endpoints: dashboard, alerts, preferences, browse, audit, chat history","p95":800},"search":{"description":"Log search: levels / service / date range / text","p95":1500},"regex":{"description":"Log regex search","p95":1500},"export":{"description":"Log export (CSV, capped)","p95":3000},"login":{"description":"Login (bcrypt)","p95":1500},"chat":{"description":"Assistant answer on the mock provider (a live model will be slower: set with Urbani)","p95":3000}},"overall":{"errorRate":0.01,"p99":5000}};
// <<< inputs

const BASE_URL = (__ENV.BASE_URL || '').replace(/\/$/, '');
const PROFILE = __ENV.PROFILE || 'realistic';
const profile = DEF.profiles[PROFILE];
if (!BASE_URL) throw new Error('BASE_URL is required, e.g. -e BASE_URL=http://127.0.0.1:4100');
if (!profile) throw new Error('unknown PROFILE ' + PROFILE);
const THINK_SCALE = Number(__ENV.THINK_SCALE || 1);
const T_SCALE = Number(__ENV.THRESHOLD_SCALE || 1);
const VUS = Number(__ENV.VUS || profile.defaults.vus);

let weights = Object.assign({}, profile.weights);
if (__ENV.SCENARIOS) {
  const only = __ENV.SCENARIOS.split(',');
  weights = {};
  only.forEach((s) => { weights[s] = profile.weights[s] || 1; });
}

const toSeconds = (s) => {
  const m = /^(\d+(?:\.\d+)?)(ms|s|m|h)?$/.exec(String(s));
  const mult = { ms: 0.001, s: 1, m: 60, h: 3600 }[(m && m[2]) || 's'];
  return Math.round(Number(m[1]) * mult);
};
const DURATION = toSeconds(__ENV.DURATION || profile.defaults.duration);
const RAMP = toSeconds(__ENV.RAMP || profile.defaults.rampUp);
const stage = (seconds, target) => ({ duration: seconds + 's', target: target });

function stages() {
  if ((profile.defaults.shape || 'ramp') === 'spike') {
    const base = Math.max(1, Math.floor(VUS / 4));
    const third = Math.max(1, Math.floor(DURATION / 3));
    return [stage(RAMP, base), stage(third - RAMP, base), stage(RAMP, VUS), stage(third - RAMP, VUS), stage(RAMP, base), stage(third, base)];
  }
  return [stage(RAMP, VUS), stage(Math.max(1, DURATION - RAMP), VUS), stage(5, 0)];
}

// Same limits as thresholds.json; latency limits stretched by THRESHOLD_SCALE, error rate never.
const thresholds = {};
Object.keys(THRESHOLDS.groups).forEach((g) => {
  const t = THRESHOLDS.groups[g];
  const rules = ['p50', 'p90', 'p95', 'p99'].filter((k) => t[k] !== undefined).map((k) => 'p(' + k.slice(1) + ')<' + t[k] * T_SCALE);
  thresholds['http_req_duration{rgroup:' + g + '}'] = rules;
});
const o = THRESHOLDS.overall || {};
thresholds['dpi_errors'] = ['rate<' + (o.errorRate !== undefined ? o.errorRate : 0.01)];
if (o.p99 !== undefined) thresholds['http_req_duration'] = ['p(99)<' + o.p99 * T_SCALE];

export const options = {
  scenarios: { dpi: { executor: 'ramping-vus', startVUs: 0, stages: stages(), gracefulRampDown: '10s', gracefulStop: '30s' } },
  thresholds: thresholds,
  tags: { suite: 'dpi2-load', profile: PROFILE },
  summaryTrendStats: ['avg', 'min', 'med', 'p(90)', 'p(95)', 'p(99)', 'max'],
};

const errors = new Rate('dpi_errors');

// ---- helpers shared in spirit with load/lib/shared.mjs
function pick(list) { return list[Math.floor(Math.random() * list.length)]; }
function resolve(value, ctx) {
  if (typeof value === 'string') {
    return value.replace(/\{\{([^}]+)\}\}/g, function (_m, key) {
      if (key.indexOf('pick:') === 0) return pick(key.slice(5).split('|'));
      return ctx[key] !== undefined ? ctx[key] : '';
    });
  }
  if (Array.isArray(value)) return value.map((v) => resolve(v, ctx));
  if (value && typeof value === 'object') {
    const out = {};
    Object.keys(value).forEach((k) => { out[k] = resolve(value[k], ctx); });
    return out;
  }
  return value;
}
function hasPath(obj, dotted) {
  let cur = obj;
  const parts = dotted.split('.');
  for (let i = 0; i < parts.length; i++) {
    if (cur === null || typeof cur !== 'object' || !(parts[i] in cur)) return false;
    cur = cur[parts[i]];
  }
  return true;
}
function pickScenario() {
  const ids = Object.keys(weights);
  let total = 0;
  ids.forEach((i) => { total += weights[i]; });
  let roll = Math.random() * total;
  for (let i = 0; i < ids.length; i++) { roll -= weights[ids[i]]; if (roll < 0) return ids[i]; }
  return ids[ids.length - 1];
}
function qs(query) {
  return Object.keys(query).map((k) => encodeURIComponent(k) + '=' + encodeURIComponent(query[k])).join('&');
}

export function setup() {
  const username = __ENV.USERNAME || 'admin@urbani.local';
  const password = __ENV.PASSWORD || '';
  const res = http.post(BASE_URL + '/api/auth/login', JSON.stringify({ email: username, password: password }), { headers: { 'Content-Type': 'application/json' }, tags: { rgroup: 'login', name: 'setup.login' } });
  if (res.status !== 200) throw new Error('setup login failed with HTTP ' + res.status + ' (set -e USERNAME / PASSWORD)');
  const token = res.json('token');
  const alerts = http.get(BASE_URL + '/api/alerts?pageSize=1', { headers: { Authorization: 'Bearer ' + token }, tags: { name: 'setup.alerts' } });
  let alertId = '';
  try { alertId = alerts.json('data.items.0.alertId') || ''; } catch (e) { alertId = ''; }
  return { token: token, ctx: { email: username, password: password, alertId: alertId, from: DEF.data.from, to: DEF.data.to } };
}

export default function (data) {
  const sid = pickScenario();
  const sc = DEF.scenarios[sid];
  for (let i = 0; i < sc.requests.length; i++) {
    const r = sc.requests[i];
    const url = BASE_URL + resolve(r.path, data.ctx) + (r.query ? '?' + qs(resolve(r.query, data.ctx)) : '');
    const headers = {};
    if (sid !== 'auth' || r.name !== 'auth.login') { if (sid !== 'auth') headers.Authorization = 'Bearer ' + data.token; }
    let body = null;
    if (r.body) { body = JSON.stringify(resolve(r.body, data.ctx)); headers['Content-Type'] = 'application/json'; }
    const params = {
      headers: headers,
      tags: { rgroup: r.group, name: r.name, scenario_name: sid },
      responseCallback: http.expectedStatuses.apply(null, r.expect),
      timeout: '60s',
    };
    const res = r.method === 'GET' ? http.get(url, params) : http.request(r.method, url, body, params);
    let ok = r.expect.indexOf(res.status) !== -1;
    if (ok && r.jsonHas) {
      let json = null;
      try { json = res.json(); } catch (e) { ok = false; }
      if (ok) ok = r.jsonHas.every((p) => hasPath(json, p));
    }
    if (ok && r.header) ok = Object.keys(r.header).every((h) => String(res.headers[h] || res.headers[h.replace(/(^|-)([a-z])/g, (m, a, b) => a + b.toUpperCase())] || '').indexOf(r.header[h]) !== -1);
    check(res, { [r.name + ' ok']: () => ok });
    errors.add(!ok);
    const t = sc.think;
    sleep(THINK_SCALE * (t[0] + Math.random() * (t[1] - t[0])) / 1000);
  }
}
